    self.size = size
    self.input_size = size
    self.dtype = dtype

  def __call__(self, t, residual=False, **_):
    one_hot = tf.one_hot(t, self.size, 1., 0.)

    if residual:
      logits = math.log(self.size * 10) * one_hot
      return logits
    else:
